{"implementation":"def solve(case):
    # Validate required fields
    if not isinstance(case, dict) or 'tokens' not in case or 'calls' not in case:
        raise ValueError("Missing required fields 'tokens' or 'calls'")
    tokens = case['tokens']
    calls = case['calls']
    if not isinstance(tokens, list) or not all(isinstance(t, str) for t in tokens):
        raise ValueError("'tokens' must be a list of strings")
    if not isinstance(calls, list):
        raise ValueError("'calls' must be a list")
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("Each call must be a dict")
        for key in ['call_id', 'start', 'end', 'score', 'replacement_tokens']:
            if key not in call:
                raise ValueError(f"Call missing required field '{key}'")
        if not isinstance(call['call_id'], str):
            raise ValueError("'call_id' must be a string")
        if not isinstance(call['start'], int) or not isinstance(call['end'], int):
            raise ValueError("'start' and 'end' must be integers")
        if not isinstance(call['score'], (int, float)):
            raise ValueError("'score' must be a number")
        if not isinstance(call['replacement_tokens'], list) or not all(isinstance(r, str) for r in call['replacement_tokens']):
            raise ValueError("'replacement_tokens' must be a list of strings")
        if call['start'] < 0 or call['end'] <= call['start'] or call['end'] > len(tokens):
            raise ValueError("Invalid span: start < 0, end <= start, or end > len(tokens)")

    # Rank calls: descending score, then start, then call_id (string order)
    ranked = sorted(calls, key=lambda c: (-c['score'], c['start'], c['call_id']))
    selected = []
    intervals = []  # list of (start, end) for already selected calls
    for call in ranked:
        s, e = call['start'], call['end']
        overlap = False
        for s2, e2 in intervals:
            if max(s, s2) < min(e, e2):  # half-open interval overlap check
                overlap = True
                break
        if not overlap:
            selected.append(call)
            intervals.append((s, e))

    # Order selected calls by start (ascending) for output
    selected_sorted = sorted(selected, key=lambda c: c['start'])
    selected_call_ids = [c['call_id'] for c in selected_sorted]

    # Apply replacements from right to left to preserve indices
    result_tokens = list(tokens)  # copy to avoid mutation
    for call in sorted(selected_sorted, key=lambda c: -c['start']):
        s, e = call['start'], call['end']
        repl = call['replacement_tokens']
        result_tokens = result_tokens[:s] + repl + result_tokens[e:]

    return {"selected_call_ids": selected_call_ids, "tokens": result_tokens}
